const row = $input.first().json;
const data = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;

const dayNames = ['Sekmadienis', 'Pirmadienis', 'Antradienis', 'Tre\u010diadienis', 'Ketvirtadienis', 'Penktadienis', '\u0160e\u0161tadienis'];
const now = new Date();
const dayName = dayNames[now.getDay()];
const dateStr = `${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;

function fmtBooking(b) {
  const statusIcons = { 'Confirmed': '\ud83d\udfe1', 'Delivered': '\ud83d\ude9b', 'Completed': '\u2705' };
  const payIcon = b.payment_status === 'Paid' ? '\ud83d\udcb0' : (b.deposit_paid ? '\ud83d\udd35' : '\ud83d\udd34');
  const icon = statusIcons[b.status] || '\u2b1c';
  const equip = Array.isArray(b.equipment) ? b.equipment.map(e => e.icon || '\ud83c\udfaa').join('') : '';
  let line = `${icon} <b>#${b.id}</b> ${(b.event_time||'?').substring(0,5)} \u2192 ${(b.pickup_time||'?').substring(0,5)}`;
  line += `\n   \ud83d\udccd ${b.delivery_address}, ${b.city}`;
  line += `\n   \ud83d\udc64 ${b.customer_name} | ${payIcon} \u20ac${b.price||0}`;
  if (!b.deposit_paid && b.status === 'Confirmed') line += ` \u26a0\ufe0f`;
  return line;
}

const today = data.today || [];
const tomorrow = data.tomorrow || [];
const unpaid = data.unpaid_deposits || [];
const cleaning = data.needs_cleaning || [];
const stats = data.stats || {};

// Build morning briefing
let msg = `\u2600\ufe0f <b>Ryto ataskaita \u2014 ${dateStr} (${dayName})</b>\n`;
msg += `\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n`;

// Today's bookings
if (today.length === 0) {
  msg += `\ud83d\udcc5 <b>\u0160iandien:</b> U\u017esakym\u0173 n\u0117ra \ud83c\udf89\n\n`;
} else {
  msg += `\ud83d\udcc5 <b>\u0160iandien (${today.length} u\u017es.):</b>\n`;
  today.forEach(b => { msg += fmtBooking(b) + '\n'; });
  msg += '\n';
}

// Tomorrow preview
if (tomorrow.length > 0) {
  msg += `\ud83d\udcc6 <b>Rytoj (${tomorrow.length} u\u017es.):</b>\n`;
  tomorrow.forEach(b => {
    msg += `  \ud83d\udfe1 #${b.id} ${(b.event_time||'?').substring(0,5)} \u2014 ${b.city} (${b.customer_name})\n`;
  });
  msg += '\n';
}

// Unpaid deposit alerts
if (unpaid.length > 0) {
  msg += `\u26a0\ufe0f <b>Nemok\u0117ti avansai (${unpaid.length}):</b>\n`;
  unpaid.forEach(u => {
    msg += `  \ud83d\udd34 #${u.id} ${u.event_date} \u2014 ${u.customer_name} (\u20ac${u.deposit_amount}) \ud83d\udcde ${u.customer_phone}\n`;
  });
  msg += '\n';
}

// Cleaning reminders
if (cleaning.length > 0) {
  msg += `\ud83e\uddf9 <b>Reikia i\u0161valyti (${cleaning.length}):</b>\n`;
  cleaning.forEach(e => {
    msg += `  ${e.icon||'\ud83c\udfaa'} #${e.id} ${e.name} \u2014 /clean ${e.id}\n`;
  });
  msg += '\n';
}

// Quick stats
msg += `\ud83d\udcca <b>Savait\u0117:</b> ${stats.week_bookings} u\u017es. | `;
msg += `\ud83d\udcb0 M\u0117n. pajamos: \u20ac${stats.month_revenue} | `;
msg += `\ud83c\udfaa ${stats.available_equipment}/${stats.total_equipment} laisva`;

return [{ json: { message: msg } }];
